        // 写入打包时间
        onMounted(() => {
            document
                .querySelector("body")
                .setAttribute(
                    "VITE_APP_BUILDTIME",
                    import.meta.env.VITE_APP_BUILDTIME
                );
        });

        provide("ec", echarts);
        let info = { name: "张三" };
        provide("info", info);
        return {};
    },
};
</script>
