import { createRouter, createWebHistory } from "vue-router";
import role from "@/router/modules/role.js"; // 角色
import backpack from "@/router/modules/backpack.js"; // 背包
import sect from "@/router/modules/sect.js"; // 宗门
import fight from "@/router/modules/fight.js"; // 战斗
import rank from "@/router/modules/rank.js"; // 排行
import test from "@/router/modules/test.js"; // 测试
import dongtian from "@/router/modules/dongtian.js"; // 洞天

export const router = createRouter({
    history: createWebHistory(),
    routes: [
        {
            path: "/",
            redirect: "/Login",
        },
        {
            path: "/login",
            name: "Login", // 登录页
            component: () => import("../views/login/Login.vue"),
        },
        {
            path: "/register",
            name: "Register", // 注册页
            component: () => import("../views/login/Register.vue"),
        },
        {
            path: "/forgetPassword",
            name: "ForgetPassword", // 忘记密码
            component: () => import("../views/login/forgetPassword.vue"),
        },
        {
            path: "/center",
            name: "center", // 首页
            redirect: "/center/role",
            component: () => import("../views/Center.vue"),
            children: [
                ...role,
                ...backpack,
                ...sect,
                ...fight,
                ...rank,
                ...test,
                ...dongtian,
                {
                    path: "/center/setting",
                    name: "Setting", // 设置
                    component: () => import("../views/setting/Setting.vue"),
                },
            ],
        },
        {
            path: "/testDom",
            name: "testDom", // 测试
            component: () => import("../views/testDom.vue"),
        },
        {
            path: "/:catchAll(.*)",
            name: "Error",
            redirect: "/",
        },
    ],
});

