// i18n
import { createI18n } from "vue-i18n";
import zh from "@/assets/i18n/zh.js";
import en from "@/assets/i18n/en.js";

// development-开发 product-生产
// console.log(import.meta.env.MODE);

const i18n = createI18n({
    legacy: false,
    locale: import.meta.env.MODE === "development" ? "en" : "zh",
    fallbackLocale: import.meta.env.MODE === "development" ? "en" : "zh",
    globalInjection: true,
    messages: {
        zh: zh,
        en: en,
    },
});

export default i18n;
